import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen2Test {



    @Test
    public void testRead_WhenFinished_ReturnsMinusOne() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("test.txt");
            zos.putNextEntry(entry);
            zos.write("hello".getBytes());
            zos.closeEntry();
        }
        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();
        zais.read(new byte[5], 0, 5); // read all

        // Trigger finished state
        zais.getNextZipEntry(); 

        Assert.assertEquals(-1, zais.read(new byte[5], 0, 5));
    }













    private long calculateCRC(byte[] data) {
        CRC32 crc = new CRC32();
        crc.update(data);
        return crc.getValue();
    }
}

