import java.io.InputStream;
import java.io.PushbackInputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import java.util.zip.ZipEntry;
import java.util.zip.ZipException;
import java.util.zip.ZipOutputStream;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveInputStream;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveInputStream_read_TriageGen2Test {











    @Test
    public void testRead_StoredEntry_Success() throws IOException {
        byte[] content = "stored content".getBytes();
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry("stored.txt");
            entry.setMethod(ZipEntry.STORED);
            entry.setSize(content.length);
            entry.setCrc(calculateCRC(content));
            zos.putNextEntry(entry);
            zos.write(content);
            zos.closeEntry();
        }

        ZipArchiveInputStream zais = new ZipArchiveInputStream(new ByteArrayInputStream(baos.toByteArray()));
        zais.getNextZipEntry();

        byte[] buffer = new byte[5];
        int read = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read);
        Assert.assertArrayEquals("stored".getBytes(), buffer);

        int read2 = zais.read(buffer, 0, 5);
        Assert.assertEquals(5, read2);
        Assert.assertArrayEquals(" conte".getBytes(), buffer);
    }





    private long calculateCRC(byte[] data) {
        CRC32 crc = new CRC32();
        crc.update(data);
        return crc.getValue();
    }
}

